create or replace function public.log_payment_activity() returns trigger language plpgsql security definer set search_path = '' as $function$ begin if (new.status = 'success' and (old.status is null or old.status <> 'success')) then perform set_config('app.internal_activity_write', 'true', true); insert into public.activities (user_id,event_type,source,metadata) values (new.user_id,'payment_completed','backend',jsonb_build_object('payment_id',new.id,'amount',new.amount_mur,'subscription_id',new.subscription_id)); update public.leads set lead_stage='Subscriber',last_activity_at=now() where email=(select email from public.profiles where id=new.user_id) and status='converted'; end if; return new; end; $function$;

create or replace function public.on_payment_success_engagement() returns trigger language plpgsql security definer set search_path = '' as $function$ declare v_email text; begin if (new.status='success' and (old.status is null or old.status<>'success')) then select email into v_email from public.profiles where id=new.user_id; insert into public.email_queue(recipient,template_key,payload) values(v_email,'payment_confirmation',jsonb_build_object('amount_mur',new.amount_mur,'payment_id',new.id,'paid_at',new.paid_at)); insert into public.notifications(user_id,type,entity_id,metadata) values(new.user_id,'payment_success',new.id,jsonb_build_object('amount_mur',new.amount_mur,'message','Your contribution of Rs ' || new.amount_mur || ' was successful. Thank you!')); end if; return new; end; $function$;

create or replace function public.handle_lead_inactivation() returns trigger language plpgsql security definer set search_path = '' as $function$ declare v_email text; v_source_init_id uuid; begin if (new.status in ('cancelled','past_due')) then select email,source_initiative_id into v_email,v_source_init_id from public.profiles where id=new.user_id; update public.leads set status='inactive',last_activity_at=now() where email=v_email and source_initiative_id=v_source_init_id and status='converted'; end if; return new; end; $function$;

create or replace function public.on_subscription_created_engagement() returns trigger language plpgsql security definer set search_path = '' as $function$ begin insert into public.notifications(user_id,type,entity_id,metadata) values(new.user_id,'subscription_created',new.id,jsonb_build_object('amount_mur',new.amount_mur,'message','Monthly subscription of Rs ' || new.amount_mur || ' has been set up.')); return new; end; $function$;

revoke execute on function public.log_payment_activity() from public, anon, authenticated;
revoke execute on function public.on_payment_success_engagement() from public, anon, authenticated;
revoke execute on function public.handle_lead_inactivation() from public, anon, authenticated;
revoke execute on function public.on_subscription_created_engagement() from public, anon, authenticated;
